#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    long num = strtol(argv[1], NULL, 10);
    if (num < 0) {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (num > 1000000) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    double low = 0.0;
    double high = (double)num;
    double mid = 0.0;
    int iter = 0;
    while (iter < 100) {
        mid = (low + high) / 2.0;
        if (mid * mid == (double)num) {
            printf("%.6f\n", mid);
            return 0;
        }
        if (mid * mid < (double)num) {
            low = mid;
        } else {
            high = mid;
        }
        iter++;
    }
    printf("%.6f\n", mid);
    return 0;
}
